WITH with_windows AS (SELECT *, CORR(revenue, units) OVER (PARTITION BY product_id) AS corr_revenue_units, SUM(revenue) OVER (ORDER BY revenue, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_revenue, NTILE(5) OVER (PARTITION BY product_id, store_id ORDER BY revenue DESC, id) AS revenue_bucket, AVG(units) OVER (PARTITION BY product_id, store_id) AS product_id_avg_units FROM store_sales) SELECT id, store_id, product_id, revenue, corr_revenue_units, running_revenue, revenue_bucket, product_id_avg_units FROM with_windows ORDER BY running_revenue DESC NULLS LAST, corr_revenue_units
